 async function loadBanners(){const {data,error}=await supabase.from('store_banners').select('*').order('priority',{ascending:false}).order('created_at',{ascending:false});if(error)setError('Banners: '+error.message);else setBanners(data||[])}
 async function saveBanner(e){e.preventDefault();setBusy(true);setError('');setNotice('');const payload={...bannerForm,priority:Number(bannerForm.priority)||0};const result=bannerEditing?await supabase.from('store_banners').update(payload).eq('id',bannerEditing):await supabase.from('store_banners').insert(payload);if(result.error)setError(result.error.message);else{setBannerForm({eyebrow:'NOVEDAD KNR',title:'',description:'',image_url:'',video_url:'',link_url:'#coleccion',style:'urban',active:true,priority:0});setBannerEditing(null);setNotice('Banner guardado correctamente.');await loadBanners()}setBusy(false)}
