 async function login(e){e.preventDefault();setBusy(true);setError('');const {error}=await supabase.auth.signInWithPassword({email,password});if(error)setError('No fue posible iniciar sesión. Verifica tus credenciales y que el usuario administrador exista en Supabase.');setBusy(false)}
 async function uploadImages(){const urls=[...(form.image_urls||[])];for(const file of files){const path=`${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'-')}`;const {error}=await supabase.storage.from('product-media').upload(path,file,{upsert:false});if(error)throw error;const {data}=supabase.storage.from('product-media').getPublicUrl(path);urls.push(data.publicUrl)}return urls}
 async function save(e){
  e.preventDefault();
  if(savingProduct)return;
  const basePrice=Number(form.price);
  if(!form.name.trim()){setError('Escribe el nombre del producto.');return}
  if(form.price===''||!Number.isFinite(basePrice)||basePrice<0){setError('Ingresa un precio válido.');return}
  if(files.some(file=>!file.type.startsWith('image/'))){setError('Selecciona únicamente archivos de imagen.');return}
  if(files.some(file=>file.size>10*1024*1024)){setError('Cada fotografía debe pesar máximo 10 MB.');return}
  setSavingProduct(true);setError('');setNotice('');
  try{
   const {data:userData,error:userError}=await supabase.auth.getUser();
   if(userError||!userData?.user)throw new Error('Tu sesión de administrador no está activa. Cierra sesión y vuelve a entrar.');
   const {data:membership,error:membershipError}=await supabase.from('admin_users').select('user_id').eq('user_id',userData.user.id).maybeSingle();
   if(membershipError)throw new Error('No se pudo comprobar el permiso de administrador: '+membershipError.message);
   if(!membership)throw new Error('Esta cuenta puede entrar al panel, pero no figura en admin_users. Hay que autorizarla en Supabase antes de guardar productos.');
   const image_urls=await uploadImages();
   const percentage=Math.round(Math.min(90,Math.max(0,Number(form.discount)||0)));
   const payload={name:form.name.trim(),category:form.category,style:form.style,price:Math.round(basePrice*(1-percentage/100)),old_price:percentage>0?Math.round(basePrice):null,discount:percentage,tag:form.tag,description:form.description,specs:form.specs.split('\n').map(x=>x.trim()).filter(Boolean),image_urls,video_url:form.video_url||null,stock:Math.max(0,Math.floor(Number(form.stock)||0)),track_inventory:!!form.track_inventory,reorder_level:Math.max(0,Math.floor(Number(form.reorder_level)||0)),reorder_quantity:Math.max(1,Math.floor(Number(form.reorder_quantity)||1)),active:form.active};
   const result=editing
    ?await supabase.from('products').update(payload).eq('id',editing).select('*').single()
    :await supabase.from('products').insert(payload).select('*').single();
   if(result.error)throw new Error('Supabase rechazó el producto: '+result.error.message);
   if(!result.data?.id)throw new Error('Supabase no devolvió el producto guardado. No se puede confirmar el registro.');
   const productId=result.data.id;
   const savedProduct=result.data;
   setItems(current=>editing?current.map(item=>item.id===productId?savedProduct:item):[savedProduct,...current]);
   setForm(blank);setFiles([]);setEditing(null);
   setNotice(editing?'Cambios guardados correctamente.':'¡Producto guardado en Supabase y añadido al catálogo!');
   document.getElementById('product-editor')?.scrollIntoView({behavior:'smooth',block:'start'});
  }catch(e){setError(e.message||'No se pudo guardar el producto. Revisa la conexión y los permisos de Supabase.')}
  finally{setSavingProduct(false)}
 }
 function edit(p){setEditing(p.id);setForm({...p,price:p.old_price??p.price,specs:(p.specs||[]).join('\n'),image_urls:p.image_urls||[],stock:p.stock??0,track_inventory:!!p.track_inventory,reorder_level:p.reorder_level??5,reorder_quantity:p.reorder_quantity??10});setFiles([]);setError('');setNotice('Editando: '+p.name);document.getElementById('product-editor')?.scrollIntoView({behavior:'smooth',block:'start'})}
 async function remove(p){if(!confirm(`¿Eliminar “${p.name}” del catálogo?`))return;const {error}=await supabase.from('products').delete().eq('id',p.id);if(error)setError(error.message);else{setNotice('Producto eliminado.');load()}}
